class_name BattleLineOfSightService
extends RefCounted

const BattleState := preload("res://battle/core/battle_state.gd")
const BattleParticipant := preload("res://battle/core/battle_participant.gd")
const BattlefieldGeometry := preload("res://battle/geometry/battlefield_geometry.gd")
const BattleObstacle := preload("res://battle/geometry/battle_obstacle.gd")
const BattleSpatialService := preload("res://battle/geometry/battle_spatial_service.gd")
const BattleLineOfSightResult := preload("res://battle/combat/battle_line_of_sight_result.gd")

# Geometric contact tolerance only. Not perception range, weapon range, or cover.
const LINE_OF_SIGHT_EPSILON := 0.0001


static func check_participant_to_participant(
	battle_state: BattleState,
	source_participant_id: String,
	target_participant_id: String
) -> BattleLineOfSightResult:
	var geometry_error: BattleLineOfSightResult = _validate_geometry(
		battle_state,
		source_participant_id,
		target_participant_id
	)
	if geometry_error != null:
		return geometry_error
	if source_participant_id.is_empty() or not battle_state.has_participant(source_participant_id):
		return BattleLineOfSightResult.failed(
			"source_not_found",
			"Battle line of sight failed: source participant was not found.",
			source_participant_id,
			target_participant_id
		)
	if target_participant_id.is_empty() or not battle_state.has_participant(target_participant_id):
		return BattleLineOfSightResult.failed(
			"target_not_found",
			"Battle line of sight failed: target participant was not found.",
			source_participant_id,
			target_participant_id
		)
	var source: BattleParticipant = battle_state.get_participant(source_participant_id)
	var target: BattleParticipant = battle_state.get_participant(target_participant_id)
	if not _is_eligible_endpoint(source):
		return BattleLineOfSightResult.failed(
			"source_not_eligible",
			"Battle line of sight failed: source participant is not eligible.",
			source_participant_id,
			target_participant_id
		)
	if not _is_eligible_endpoint(target):
		return BattleLineOfSightResult.failed(
			"target_not_eligible",
			"Battle line of sight failed: target participant is not eligible.",
			source_participant_id,
			target_participant_id
		)
	return _trace_segment_cached(
		battle_state,
		source.battle_position,
		target.battle_position,
		source_participant_id,
		target_participant_id
	)


static func check_segment(
	battle_state: BattleState,
	start_position: Vector2,
	end_position: Vector2
) -> BattleLineOfSightResult:
	var geometry_error: BattleLineOfSightResult = _validate_geometry(battle_state, "", "")
	if geometry_error != null:
		return geometry_error
	if not BattlefieldGeometry.is_finite_point(start_position) or not BattlefieldGeometry.is_finite_point(end_position):
		return BattleLineOfSightResult.failed(
			"invalid_segment",
			"Battle line of sight failed: segment endpoints are invalid."
		)
	return _trace_segment_cached(
		battle_state,
		start_position,
		end_position,
		"",
		""
	)


static func _validate_geometry(
	battle_state: BattleState,
	source_participant_id: String,
	target_participant_id: String
) -> BattleLineOfSightResult:
	if battle_state == null:
		return BattleLineOfSightResult.failed(
			"null_battle_state",
			"Battle line of sight failed: battle_state is null.",
			source_participant_id,
			target_participant_id
		)
	if battle_state.battlefield_geometry == null:
		return BattleLineOfSightResult.failed(
			"missing_battlefield_geometry",
			"Battle line of sight failed: battlefield geometry is missing.",
			source_participant_id,
			target_participant_id
		)
	if not battle_state.has_valid_geometry():
		return BattleLineOfSightResult.failed(
			"invalid_battlefield_geometry",
			"Battle line of sight failed: battlefield geometry is invalid.",
			source_participant_id,
			target_participant_id
		)
	return null


static func _is_eligible_endpoint(participant: BattleParticipant) -> bool:
	if participant == null:
		return false
	if not participant.is_alive:
		return false
	if not participant.has_battle_position:
		return false
	return BattlefieldGeometry.is_finite_point(participant.battle_position)


static func _trace_segment_cached(
	battle_state: BattleState,
	start_position: Vector2,
	end_position: Vector2,
	source_participant_id: String,
	target_participant_id: String
) -> BattleLineOfSightResult:
	var cached: Variant = battle_state.los_cache_lookup(start_position, end_position)
	if cached is Dictionary:
		var cached_row: Dictionary = cached
		return BattleLineOfSightResult.succeeded(
			bool(cached_row.get("has_los", false)),
			source_participant_id,
			target_participant_id,
			str(cached_row.get("blocking_obstacle_id", ""))
		)
	var result: BattleLineOfSightResult = _trace_segment(
		battle_state.battlefield_geometry,
		start_position,
		end_position,
		source_participant_id,
		target_participant_id
	)
	if result != null and result.success:
		battle_state.los_cache_store(
			start_position,
			end_position,
			result.has_line_of_sight,
			result.blocking_obstacle_id
		)
	return result


# Future elevation-aware visibility (source/target elevation_level, obstacle
# height/occupancy) belongs here. Callers should keep using this service rather
# than branching on elevation themselves. Current combat is flat level 0.
static func _trace_segment(
	geometry: BattlefieldGeometry,
	start_position: Vector2,
	end_position: Vector2,
	source_participant_id: String,
	target_participant_id: String
) -> BattleLineOfSightResult:
	var displacement: Vector2 = end_position - start_position
	if not BattlefieldGeometry.is_finite_point(displacement):
		return BattleLineOfSightResult.failed(
			"invalid_segment",
			"Battle line of sight failed: segment displacement is invalid.",
			source_participant_id,
			target_participant_id
		)
	if (
		start_position.is_equal_approx(end_position)
		or displacement.length() <= LINE_OF_SIGHT_EPSILON
	):
		return BattleLineOfSightResult.succeeded(
			true,
			source_participant_id,
			target_participant_id,
			""
		)
	var segment_bounds: Rect2 = Rect2(start_position.min(end_position), displacement.abs()).grow(LINE_OF_SIGHT_EPSILON)
	var best_t: float = INF
	var best_obstacle_id: String = ""
	var obstacle_ids: Array[String] = geometry.get_obstacle_ids_in_rect(segment_bounds)
	for obstacle_id: String in obstacle_ids:
		var obstacle: BattleObstacle = geometry.get_obstacle(obstacle_id)
		if obstacle == null or not obstacle.blocks_line_of_sight:
			continue
		if not obstacle.bounds.intersects(segment_bounds, true):
			continue
		if not obstacle.bounds_are_usable():
			continue
		var interior: Rect2 = _interior_bounds(obstacle.bounds)
		if not BattlefieldGeometry.rect_is_usable(interior):
			continue
		var overlap: Vector2 = BattleSpatialService.segment_aabb_overlap_t(
			start_position,
			displacement,
			interior
		)
		if overlap.x > overlap.y:
			continue
		var vis_enter: float = maxf(overlap.x, 0.0)
		var vis_exit: float = minf(overlap.y, 1.0)
		if vis_exit - vis_enter <= LINE_OF_SIGHT_EPSILON:
			continue
		var hit_t: float = vis_enter
		if hit_t < best_t and not is_equal_approx(hit_t, best_t):
			best_t = hit_t
			best_obstacle_id = obstacle_id
			continue
		if is_equal_approx(hit_t, best_t):
			if best_obstacle_id.is_empty() or obstacle_id < best_obstacle_id:
				best_t = hit_t
				best_obstacle_id = obstacle_id
	if best_obstacle_id.is_empty():
		return BattleLineOfSightResult.succeeded(
			true,
			source_participant_id,
			target_participant_id,
			""
		)
	return BattleLineOfSightResult.succeeded(
		false,
		source_participant_id,
		target_participant_id,
		best_obstacle_id
	)


static func _interior_bounds(bounds: Rect2) -> Rect2:
	return Rect2(
		bounds.position.x + LINE_OF_SIGHT_EPSILON,
		bounds.position.y + LINE_OF_SIGHT_EPSILON,
		bounds.size.x - (LINE_OF_SIGHT_EPSILON * 2.0),
		bounds.size.y - (LINE_OF_SIGHT_EPSILON * 2.0)
	)

battle/combat/battle_defend_position_ser:
class_name BattleDefendPositionService
extends RefCounted

# Query-only local Defend Position search. Behavior owns reservation and navigation.
# Reuses BattleCombatCoverEvaluationService ranking. Does not chase.

const BattleState := preload("res://battle/core/battle_state.gd")
const BattleParticipant := preload("res://battle/core/battle_participant.gd")
const BattlefieldGeometry := preload("res://battle/geometry/battlefield_geometry.gd")
const BattleObstacle := preload("res://battle/geometry/battle_obstacle.gd")
const BattleCoverSlot := preload("res://battle/geometry/battle_cover_slot.gd")
const BattleCoverService := preload("res://battle/geometry/battle_cover_service.gd")
const BattleLineOfSightService := preload("res://battle/combat/battle_line_of_sight_service.gd")
const BattleLineOfSightResult := preload("res://battle/combat/battle_line_of_sight_result.gd")
const BattleNavigationService := preload("res://battle/navigation/battle_navigation_service.gd")
const BattleNavigationResult := preload("res://battle/navigation/battle_navigation_result.gd")
const BattleCombatCoverEvaluation := preload("res://battle/combat/battle_combat_cover_evaluation.gd")
const BattleCombatCoverEvaluationService := preload(
	"res://battle/combat/battle_combat_cover_evaluation_service.gd"
)
const BattleCombatBehaviorCatalog := preload("res://battle/combat/battle_combat_behavior_catalog.gd")
const BattleWeaponCatalog := preload("res://battle/combat/battle_weapon_catalog.gd")
const BattleWeaponDefinition := preload("res://battle/combat/battle_weapon_definition.gd")


static func defend_anchor(participant: BattleParticipant) -> Vector2:
	if participant == null:
		return Vector2.INF
	if participant.has_defend_position_anchor and BattlefieldGeometry.is_finite_point(
		participant.defend_position_anchor
	):
		return participant.defend_position_anchor
	if participant.has_battle_position and BattlefieldGeometry.is_finite_point(participant.battle_position):
		return participant.battle_position
	return Vector2.INF


static func is_within_defend_radius(origin: Vector2, point: Vector2) -> bool:
	if not BattlefieldGeometry.is_finite_point(origin) or not BattlefieldGeometry.is_finite_point(point):
		return false
	var distance: float = origin.distance_to(point)
	if not is_finite(distance):
		return false
	var radius: float = BattleCombatBehaviorCatalog.DEFEND_POSITION_RADIUS
	return distance < radius or is_equal_approx(distance, radius)


static func select_best_local_cover_slot(
	battle_state: BattleState,
	participant: BattleParticipant,
	hostile: BattleParticipant
) -> BattleCoverSlot:
	var origin: Vector2 = defend_anchor(participant)
	if not BattlefieldGeometry.is_finite_point(origin):
		return null
	# If even the nearest point in the allowed radius cannot reach the target,
	# the existing range-filtered cover search is necessarily empty.
	if hostile != null and _is_positioned(hostile):
		var weapon: BattleWeaponDefinition = BattleWeaponCatalog.for_participant(participant)
		if weapon != null and weapon.is_valid() and participant.battle_position.distance_to(hostile.battle_position) > weapon.max_range:
			var minimum_range: float = origin.distance_to(hostile.battle_position) - BattleCombatBehaviorCatalog.DEFEND_POSITION_RADIUS
			if minimum_range > weapon.max_range and not is_equal_approx(minimum_range, weapon.max_range):
				return null
	var ranked: Array[BattleCombatCoverEvaluation] = (
		BattleCombatCoverEvaluationService.rank_combat_usable_within_radius(
			battle_state,
			participant,
			hostile,
			true,
			origin,
			BattleCombatBehaviorCatalog.DEFEND_POSITION_RADIUS
		)
	)
	if ranked.is_empty():
		ranked = BattleCombatCoverEvaluationService.rank_combat_usable_within_radius(
			battle_state,
			participant,
			hostile,
			false,
			origin,
			BattleCombatBehaviorCatalog.DEFEND_POSITION_RADIUS
		)
	if hostile != null:
		var weapon = BattleWeaponCatalog.for_participant(participant)
		var current_range: float = participant.battle_position.distance_to(hostile.battle_position)
		if weapon != null and current_range > weapon.max_range:
			ranked = ranked.filter(func(e): return battle_state.battlefield_geometry.get_cover_slot(e.slot_id).position.distance_to(hostile.battle_position) <= weapon.max_range)
	return BattleCombatCoverEvaluationService.first_reachable_ranked_slot(
		battle_state,
		participant,
		ranked,
		true
	)


static func select_best_local_los_point(
	battle_state: BattleState,
	participant: BattleParticipant,
	hostile: BattleParticipant
) -> Vector2:
	if participant == null or hostile == null or not _is_positioned(participant) or not _is_positioned(hostile):
		return Vector2.INF
	var origin: Vector2 = defend_anchor(participant)
	if not BattlefieldGeometry.is_finite_point(origin):
		return Vector2.INF
	var candidates: Array[Dictionary] = []
	var order := 0
	var radii: Array[float] = _sample_radii()
	var directions: int = BattleCombatBehaviorCatalog.DEFEND_POSITION_SAMPLE_DIRECTIONS
	for radius: float in radii:
		var dir := 0
		while dir < directions:
			order += 1
			var angle: float = (float(dir) * TAU) / float(directions)
			var point: Vector2 = origin + Vector2.from_angle(angle) * radius
			dir += 1
			if not _sample_is_legal(battle_state, participant, hostile, origin, point, false):
				continue
			var move_distance: float = participant.battle_position.distance_to(point)
			var anchor_distance: float = point.distance_to(origin)
			if not is_finite(move_distance) or not is_finite(anchor_distance):
				continue
			candidates.append({
				"point": point,
				"move": move_distance,
				"anchor": anchor_distance,
				"order": order,
			})
	candidates.sort_custom(_compare_defend_samples)
	var best: Vector2 = Vector2.INF
	for candidate: Dictionary in candidates:
		var point: Vector2 = candidate["point"]
		if participant.battle_position.distance_to(point) <= BattleCoverService.COVER_OCCUPANCY_EPSILON:
			best = point
			break
		if BattleNavigationService.is_reachable(battle_state, participant.battle_position, point):
			best = point
			break
	return best


static func destination_still_valid(
	battle_state: BattleState,
	participant: BattleParticipant,
	hostile: BattleParticipant,
	destination: Vector2,
	require_reachable: bool = true
) -> bool:
	if participant == null or not _is_positioned(participant):
		return false
	var origin: Vector2 = defend_anchor(participant)
	return _sample_is_legal(
		battle_state,
		participant,
		hostile,
		origin,
		destination,
		require_reachable
	)


static func _sample_radii() -> Array[float]:
	var radii: Array[float] = [
		BattleCombatBehaviorCatalog.DEFEND_POSITION_SAMPLE_RADIUS_A,
		BattleCombatBehaviorCatalog.DEFEND_POSITION_SAMPLE_RADIUS_B,
		BattleCombatBehaviorCatalog.DEFEND_POSITION_SAMPLE_RADIUS_C,
		BattleCombatBehaviorCatalog.DEFEND_POSITION_SAMPLE_RADIUS_D,
	]
	return radii


static func _compare_defend_samples(left: Dictionary, right: Dictionary) -> bool:
	return _sample_ranks_better(
		float(left.get("move", INF)),
		float(left.get("anchor", INF)),
		int(left.get("order", 2147483647)),
		float(right.get("move", INF)),
		float(right.get("anchor", INF)),
		int(right.get("order", 2147483647))
	)


static func _sample_ranks_better(
	move_distance: float,
	anchor_distance: float,
	order: int,
	best_move: float,
	best_anchor: float,
	best_order: int
) -> bool:
	if not is_equal_approx(move_distance, best_move):
		return move_distance < best_move
	if not is_equal_approx(anchor_distance, best_anchor):
		return anchor_distance < best_anchor
	return order < best_order


static func _sample_is_legal(
	battle_state: BattleState,
	participant: BattleParticipant,
	hostile: BattleParticipant,
	origin: Vector2,
	point: Vector2,
	require_reachable: bool = true
) -> bool:
	if not BattlefieldGeometry.is_finite_point(point):
		return false
	if participant != null and point.is_equal_approx(participant.battle_position):
		return false
	if not is_within_defend_radius(origin, point):
		return false
	if not _point_is_in_weapon_max_range(participant, point, hostile):
		return false
	if not _is_valid_destination(battle_state, point):
		return false
	if not _point_has_los_to_hostile(battle_state, point, hostile):
		return false
	if participant == null or not _is_positioned(participant):
		return false
	if participant.battle_position.distance_to(point) <= BattleCoverService.COVER_OCCUPANCY_EPSILON:
		return true
	if not require_reachable:
		return true
	return BattleNavigationService.is_reachable(
		battle_state,
		participant.battle_position,
		point
	)


static func _point_has_los_to_hostile(
	battle_state: BattleState,
	point: Vector2,
	hostile: BattleParticipant
) -> bool:
	if hostile == null or not _is_positioned(hostile):
		return false
	var los: BattleLineOfSightResult = BattleLineOfSightService.check_segment(
		battle_state,
		point,
		hostile.battle_position
	)
	return los != null and los.success and los.has_line_of_sight


static func _point_is_in_weapon_max_range(
	participant: BattleParticipant,
	point: Vector2,
	hostile: BattleParticipant
) -> bool:
	if participant == null or hostile == null or not _is_positioned(hostile):
		return false
	if not BattlefieldGeometry.is_finite_point(point):
		return false
	var weapon_type_id: String = participant.weapon_type
	if participant.weapon_state != null and not participant.weapon_state.weapon_type_id.is_empty():
		weapon_type_id = participant.weapon_state.weapon_type_id
	var definition: BattleWeaponDefinition = BattleWeaponCatalog.for_participant(participant)
	if definition == null or not definition.is_valid():
		return false
	var distance: float = point.distance_to(hostile.battle_position)
	if not is_finite(distance):
		return false
	return distance < definition.max_range or is_equal_approx(distance, definition.max_range)


static func _is_valid_destination(battle_state: BattleState, point: Vector2) -> bool:
	if battle_state == null or battle_state.battlefield_geometry == null:
		return false
	if not BattlefieldGeometry.is_finite_point(point):
		return false
	var geometry: BattlefieldGeometry = battle_state.battlefield_geometry
	if not geometry.contains_point(point):
		return false
	for obstacle_id: String in geometry.get_obstacle_ids_at_point(point):
		var obstacle: BattleObstacle = geometry.get_obstacle(obstacle_id)
		if obstacle == null or not obstacle.blocks_movement:
			continue
		if obstacle.contains_point(point):
			return false
	return true


static func _is_positioned(participant: BattleParticipant) -> bool:
	if participant == null:
		return false
	if not participant.has_battle_position:
		return false
	return BattlefieldGeometry.is_finite_point(participant.battle_position)

battle/navigation/battle_navigation_serv:
class_name BattleNavigationService
extends RefCounted

const BattleState := preload("res://battle/core/battle_state.gd")
const BattlefieldGeometry := preload("res://battle/geometry/battlefield_geometry.gd")
const BattleObstacle := preload("res://battle/geometry/battle_obstacle.gd")
const BattleVehicle := preload("res://battle/core/battle_vehicle.gd")
const BattleVehicleBodyService := preload("res://battle/vehicles/battle_vehicle_body_service.gd")
const BattleSpatialService := preload("res://battle/geometry/battle_spatial_service.gd")
const BattleNavigationResult := preload("res://battle/navigation/battle_navigation_result.gd")
const BattleNavigationGraph := preload("res://battle/navigation/battle_navigation_graph.gd")

# Geometric clearance only. Matches spatial collision epsilon so planned
# segments sit outside authored blockers and positioned vehicle bodies.
# Vehicle corners are queried live from BattleState; they are not written
# into BattlefieldGeometry obstacles.
const NAVIGATION_CLEARANCE_EPSILON := 0.0001


# Reachability needs graph connectivity, not a copied graph and shortest route
# for every candidate cover slot. Actual movement still uses find_path.
static func is_reachable(battle_state: BattleState,start_position: Vector2,destination: Vector2) -> bool:
	if battle_state == null:
		return false
	var own_scope: bool = not battle_state._geometry_validation_scope
	if own_scope:
		battle_state.begin_geometry_validation_scope()
	var reachable: bool = _query_reachability(battle_state,start_position,destination)
	if own_scope:
		battle_state.end_geometry_validation_scope()
	return reachable


static func _query_reachability(battle_state: BattleState,start_position: Vector2,destination: Vector2) -> bool:
	if not battle_state.has_valid_geometry() or not _is_legal_candidate(battle_state,start_position) or not _is_legal_candidate(battle_state,destination):
		return false
	var cached: int = battle_state.nav_cache_lookup(start_position,destination)
	if cached >= 0:
		return cached == 1
	var reachable: bool = BattleSpatialService.is_translation_clear(battle_state,start_position,destination)
	if not reachable:
		var graph: BattleNavigationGraph = _ensure_static_graph(battle_state)
		if graph != null:
			var labels: Array = _component_labels(graph)
			var from_components: Dictionary = _point_components(battle_state,graph,labels,start_position)
			var to_components: Dictionary = _point_components(battle_state,graph,labels,destination)
			for component in from_components:
				if to_components.has(component):
					reachable = true
					break
	battle_state.nav_cache_store(start_position,destination,reachable)
	return reachable


static func _component_labels(graph: BattleNavigationGraph) -> Array:
	if graph.has_meta("components"):
		return graph.get_meta("components")
	var labels: Array = [];labels.resize(graph.nodes.size());labels.fill(-1)
	var component: int = 0
	for index in range(labels.size()):
		if labels[index] >= 0:
			continue
		var pending: Array = [index];labels[index] = component
		while not pending.is_empty():
			var current: int = int(pending.pop_back())
			for neighbor in graph.adjacency[current]:
				if labels[int(neighbor)] < 0:
					labels[int(neighbor)] = component;pending.append(int(neighbor))
		component += 1
	graph.set_meta("components",labels);graph.set_meta("component_count",component)
	return labels


static func _point_components(battle_state: BattleState,graph: BattleNavigationGraph,labels: Array,point: Vector2) -> Dictionary:
	# The cache belongs to this exact topology and uses unrounded endpoints.
	var cache: Dictionary = graph.get_meta("point_components", {})
	if cache.has(point):
		return cache[point]
	var found: Dictionary = {}
	var count: int = int(graph.get_meta("component_count",0))
	for index in range(graph.nodes.size()):
		if found.has(labels[index]):
			continue
		if point.is_equal_approx(graph.nodes[index]) or _segment_open(battle_state,graph.blocking_rects,point,graph.nodes[index]):
			found[labels[index]] = true
			if found.size() == count:
				break
	if cache.size() >= 1024:
		cache.clear()
	cache[point] = found
	graph.set_meta("point_components", cache)
	return found


static func prewarm(battle_state: BattleState) -> void:
	_ensure_static_graph(battle_state)


# A synchronous navigation query shares validation across all visibility edges.
# Standalone calls still revalidate; no cache survives the call or runtime tick.
static func find_path(battle_state: BattleState,start_position: Vector2,destination: Vector2) -> BattleNavigationResult:
	var own_scope: bool=battle_state!=null and not battle_state._geometry_validation_scope
	if own_scope:battle_state.begin_geometry_validation_scope()
	var result: BattleNavigationResult=_find_path(battle_state,start_position,destination)
	if own_scope:battle_state.end_geometry_validation_scope()
	return result


static func _find_path(
	battle_state: BattleState,
	start_position: Vector2,
	destination: Vector2
) -> BattleNavigationResult:
	if battle_state == null:
		return BattleNavigationResult.failed(
			"null_battle_state",
			"Battle navigation failed: battle_state is null.",
			start_position,
			destination
		)
	if battle_state.battlefield_geometry == null:
		return BattleNavigationResult.failed(
			"missing_battlefield_geometry",
			"Battle navigation failed: battlefield geometry is missing.",
			start_position,
			destination
		)
	var geometry: BattlefieldGeometry = battle_state.battlefield_geometry
	if not battle_state.has_valid_geometry():
		return BattleNavigationResult.failed(
			"invalid_battlefield_geometry",
			"Battle navigation failed: battlefield geometry is invalid.",
			start_position,
			destination
		)
	if not BattlefieldGeometry.is_finite_point(start_position):
		return BattleNavigationResult.failed(
			"invalid_start_position",
			"Battle navigation failed: start position is invalid.",
			start_position,
			destination
		)
	if not BattlefieldGeometry.is_finite_point(destination):
		return BattleNavigationResult.failed(
			"invalid_destination",
			"Battle navigation failed: destination is invalid.",
			start_position,
			destination
		)
	if not geometry.contains_point(start_position):
		return BattleNavigationResult.failed(
			"start_outside_battlefield",
			"Battle navigation failed: start position is outside the battlefield.",
			start_position,
			destination
		)
	if not geometry.contains_point(destination):
		return BattleNavigationResult.failed(
			"destination_outside_battlefield",
			"Battle navigation failed: destination is outside the battlefield.",
			start_position,
			destination
		)
	var start_obstacle_id: String = _blocking_obstacle_id(geometry, start_position)
	if not start_obstacle_id.is_empty():
		return BattleNavigationResult.failed(
			"start_inside_blocking_obstacle",
			"Battle navigation failed: start position is inside blocking obstacle '%s'." % start_obstacle_id,
			start_position,
			destination
		)
	var start_vehicle_id: String = BattleVehicleBodyService.blocking_vehicle_id_at(
		battle_state,
		start_position
	)
	if not start_vehicle_id.is_empty():
		return BattleNavigationResult.failed(
			"start_inside_vehicle",
			"Battle navigation failed: start position is inside vehicle '%s'." % start_vehicle_id,
			start_position,
			destination
		)
	var destination_obstacle_id: String = _blocking_obstacle_id(geometry, destination)
	if not destination_obstacle_id.is_empty():
		return BattleNavigationResult.failed(
			"destination_inside_blocking_obstacle",
			"Battle navigation failed: destination is inside blocking obstacle '%s'." % destination_obstacle_id,
			start_position,
			destination
		)
	var destination_vehicle_id: String = BattleVehicleBodyService.blocking_vehicle_id_at(
		battle_state,
		destination
	)
	if not destination_vehicle_id.is_empty():
		return BattleNavigationResult.failed(
			"destination_inside_vehicle",
			"Battle navigation failed: destination is inside vehicle '%s'." % destination_vehicle_id,
			start_position,
			destination
		)
	if BattleSpatialService.is_translation_clear(battle_state, start_position, destination):
		var direct_waypoints: Array[Vector2] = [destination]
		return BattleNavigationResult.succeeded(
			start_position,
			destination,
			direct_waypoints,
			false
		)
	var graph: BattleNavigationGraph = _ensure_static_graph(battle_state)
	if graph == null:
		return BattleNavigationResult.failed(
			"no_path",
			"Battle navigation failed: no legal path exists.",
			start_position,
			destination
		)
	var route: Array[Vector2] = _query_shortest_route(
		battle_state,
		graph,
		start_position,
		destination
	)
	if route.is_empty():
		return BattleNavigationResult.failed(
			"no_path",
			"Battle navigation failed: no legal path exists.",
			start_position,
			destination
		)
	var waypoints: Array[Vector2] = _simplify_route(battle_state, route)
	var used_detour: bool = _route_uses_detour(waypoints, destination)
	return BattleNavigationResult.succeeded(
		start_position,
		destination,
		waypoints,
		used_detour
	)


static func _ensure_static_graph(battle_state: BattleState) -> BattleNavigationGraph:
	if battle_state == null or battle_state.battlefield_geometry == null:
		return null
	if not battle_state.has_valid_geometry():
		return null
	var stamp: String = battle_state.navigation_topology_stamp()
	var graph: BattleNavigationGraph = battle_state.get_static_nav_graph()
	if graph != null and graph.stamp == stamp:
		return graph
	graph = BattleNavigationGraph.new()
	graph.stamp = stamp
	graph.nodes = _collect_static_nodes(battle_state)
	graph.blocking_rects = _collect_blocking_rects(battle_state)
	graph.adjacency = _build_adjacency(battle_state, graph.nodes, graph.blocking_rects)
	graph.build_count = battle_state.get_static_nav_build_count() + 1
	battle_state.increment_static_nav_build_count()
	battle_state.set_static_nav_graph(graph)
	return graph


static func _collect_static_nodes(battle_state: BattleState) -> Array[Vector2]:
	var nodes: Array[Vector2] = []
	if battle_state == null or battle_state.battlefield_geometry == null:
		return nodes
	var geometry: BattlefieldGeometry = battle_state.battlefield_geometry
	var obstacle_ids: Array[String] = geometry.get_sorted_obstacle_ids()
	for obstacle_id: String in obstacle_ids:
		var obstacle: BattleObstacle = geometry.get_obstacle(obstacle_id)
		if obstacle == null or not obstacle.blocks_movement:
			continue
		if not obstacle.bounds_are_usable():
			continue
		var corners: Array[Vector2] = _corner_offsets(obstacle.bounds)
		for corner: Vector2 in corners:
			if not _is_legal_candidate(battle_state, corner):
				continue
			if _has_equivalent_point(nodes, corner):
				continue
			nodes.append(corner)
	var vehicle_ids: Array[String] = []
	for vehicle_id: String in battle_state.vehicles:
		vehicle_ids.append(vehicle_id)
	vehicle_ids.sort()
	for vehicle_id: String in vehicle_ids:
		var vehicle: BattleVehicle = battle_state.get_vehicle(vehicle_id)
		if vehicle == null:
			continue
		var vehicle_corners: PackedVector2Array = BattleVehicleBodyService.cleared_corners(
			vehicle,
			NAVIGATION_CLEARANCE_EPSILON
		)
		for corner: Vector2 in vehicle_corners:
			if not _is_legal_candidate(battle_state, corner):
				continue
			if _has_equivalent_point(nodes, corner):
				continue
			nodes.append(corner)
	return nodes


static func _corner_offsets(bounds: Rect2) -> Array[Vector2]:
	var min_x: float = bounds.position.x
	var min_y: float = bounds.position.y
	var max_x: float = bounds.position.x + bounds.size.x
	var max_y: float = bounds.position.y + bounds.size.y
	var epsilon: float = NAVIGATION_CLEARANCE_EPSILON
	var corners: Array[Vector2] = [
		Vector2(min_x - epsilon, min_y - epsilon),
		Vector2(max_x + epsilon, min_y - epsilon),
		Vector2(min_x - epsilon, max_y + epsilon),
		Vector2(max_x + epsilon, max_y + epsilon)
	]
	return corners


static func _is_legal_candidate(battle_state: BattleState, point: Vector2) -> bool:
	if battle_state == null or battle_state.battlefield_geometry == null:
		return false
	if not BattlefieldGeometry.is_finite_point(point):
		return false
	var geometry: BattlefieldGeometry = battle_state.battlefield_geometry
	if not geometry.contains_point(point):
		return false
	if not _blocking_obstacle_id(geometry, point).is_empty():
		return false
	return BattleVehicleBodyService.blocking_vehicle_id_at(battle_state, point).is_empty()


static func _has_equivalent_point(points: Array[Vector2], candidate: Vector2) -> bool:
	for point: Vector2 in points:
		if point.is_equal_approx(candidate):
			return true
	return false


# The immutable visibility graph is shared. Only the two query endpoints are
# attached temporarily; shortest-path work runs in Godot's native AStar2D.
# All graph edges retain their original Euclidean costs and clearance checks.
static func _query_shortest_route(
	battle_state: BattleState,
	graph: BattleNavigationGraph,
	start_position: Vector2,
	destination: Vector2
) -> Array[Vector2]:
	var native: AStar2D
	if graph.has_meta("native_routes"):
		native = graph.get_meta("native_routes")
	else:
		native = AStar2D.new()
		native.reserve_space(graph.nodes.size() + 2)
		for index in range(graph.nodes.size()):
			native.add_point(index, graph.nodes[index])
		for index in range(graph.nodes.size()):
			var neighbors: Array = graph.adjacency[index].keys()
			neighbors.sort()
			for neighbor in neighbors:
				if int(neighbor) > index:
					native.connect_points(index, int(neighbor))
		graph.set_meta("native_routes", native)
	var start_id: int = graph.nodes.size()
	var end_id: int = start_id + 1
	native.add_point(start_id, start_position)
	native.add_point(end_id, destination)
	# The previous query graph omitted static points coincident with either end.
	var excluded: Array[int] = []
	for index in range(graph.nodes.size()):
		if graph.nodes[index].is_equal_approx(start_position) or graph.nodes[index].is_equal_approx(destination):
			excluded.append(index)
			native.set_point_disabled(index, true)
	for index in _endpoint_connections(battle_state, graph, start_position):
		if not native.is_point_disabled(index):
			native.connect_points(start_id, index)
	for index in _endpoint_connections(battle_state, graph, destination):
		if not native.is_point_disabled(index):
			native.connect_points(end_id, index)
	var route: Array[Vector2] = []
	for point in native.get_point_path(start_id, end_id):
		route.append(point)
	native.remove_point(start_id)
	native.remove_point(end_id)
	for index in excluded:
		native.set_point_disabled(index, false)
	return route


# Exact endpoints only: no rounding of moving actors into cached positions.
# Stored on the topology-specific graph, so obstacle/vehicle changes discard it.
static func _endpoint_connections(battle_state: BattleState, graph: BattleNavigationGraph, point: Vector2) -> Array[int]:
	var cache: Dictionary = graph.get_meta("endpoint_connections", {})
	if cache.has(point):
		return cache[point]
	var connections: Array[int] = []
	for index in range(graph.nodes.size()):
		if _segment_open(battle_state, graph.blocking_rects, point, graph.nodes[index]):
			connections.append(index)
	# Bound memory during long battles with many distinct moving endpoints.
	if cache.size() >= 512:
		cache.clear()
	cache[point] = connections
	graph.set_meta("endpoint_connections", cache)
	return connections


static func _empty_adjacency(node_count: int) -> Array:
	var adjacency: Array = []
	var index: int = 0
	while index < node_count:
		var empty_neighbors: Dictionary = {}
		adjacency.append(empty_neighbors)
		index += 1
	return adjacency


static func _shortest_route(nodes: Array[Vector2], adjacency: Array) -> Array[Vector2]:
	var node_count: int = nodes.size()
	if node_count < 2:
		return []
	var distances: Array[float] = []
	var previous: Array[int] = []
	var visited: Array[bool] = []
	distances.resize(node_count)
	previous.resize(node_count)
	visited.resize(node_count)
	for i: int in range(node_count):
		distances[i] = INF
		previous[i] = -1
		visited[i] = false
	distances[0] = 0.0
	while true:
		var current: int = _next_unvisited(distances, visited)
		if current < 0:
			break
		if is_inf(distances[current]):
			break
		visited[current] = true
		if current == 1:
			break
		var neighbor_map: Dictionary = adjacency[current]
		var neighbor_ids: Array = neighbor_map.keys()
		neighbor_ids.sort()
		for neighbor_value: Variant in neighbor_ids:
			var neighbor: int = int(neighbor_value)
			if neighbor < 0 or neighbor >= node_count:
				continue
			if visited[neighbor]:
				continue
			var weight: float = float(neighbor_map[neighbor])
			if not is_finite(weight) or weight < 0.0:
				continue
			var candidate_distance: float = distances[current] + weight
			if not is_finite(candidate_distance):
				continue
			if candidate_distance < distances[neighbor] and not is_equal_approx(candidate_distance, distances[neighbor]):
				distances[neighbor] = candidate_distance
				previous[neighbor] = current
			elif is_equal_approx(candidate_distance, distances[neighbor]):
				if previous[neighbor] < 0 or current < previous[neighbor]:
					previous[neighbor] = current
	if is_inf(distances[1]) or (previous[1] < 0 and not nodes[0].is_equal_approx(nodes[1])):
		return []
	return _reconstruct_route(nodes, previous)


static func _collect_blocking_rects(battle_state: BattleState) -> Array[Rect2]:
	var rects: Array[Rect2] = []
	if battle_state == null or battle_state.battlefield_geometry == null:
		return rects
	var geometry: BattlefieldGeometry = battle_state.battlefield_geometry
	for obstacle_id: String in geometry.get_sorted_obstacle_ids():
		var obstacle: BattleObstacle = geometry.get_obstacle(obstacle_id)
		if obstacle == null or not obstacle.blocks_movement:
			continue
		if not obstacle.bounds_are_usable():
			continue
		rects.append(obstacle.bounds)
	return rects


static func _segment_open(
	battle_state: BattleState,
	blocking_rects: Array[Rect2],
	start_position: Vector2,
	destination: Vector2
) -> bool:
	if start_position.is_equal_approx(destination):
		return true
	var displacement: Vector2 = destination - start_position
	if not BattlefieldGeometry.is_finite_point(displacement):
		return false
	var segment_bounds: Rect2 = Rect2(start_position.min(destination), displacement.abs()).grow(NAVIGATION_CLEARANCE_EPSILON)
	for rect: Rect2 in blocking_rects:
		if not rect.intersects(segment_bounds, true):
			continue
		if _segment_hits_rect(start_position, displacement, rect):
			return false
	if battle_state == null:
		return true
	for vehicle_id: String in battle_state.vehicles:
		var vehicle: BattleVehicle = battle_state.vehicles[vehicle_id]
		var hit_t: float = BattleVehicleBodyService.segment_entry_t(
			vehicle,
			start_position,
			displacement
		)
		if is_inf(hit_t):
			continue
		if hit_t < 0.0 or hit_t > 1.0:
			continue
		return false
	return true


static func _segment_hits_rect(start_position: Vector2, displacement: Vector2, rect: Rect2) -> bool:
	var overlap: Vector2 = BattleSpatialService.segment_aabb_overlap_t(start_position, displacement, rect)
	var t_enter: float = overlap.x
	var t_exit: float = overlap.y
	if t_enter > t_exit:
		return false
	if t_exit < 0.0:
		return false
	if t_enter > 1.0:
		return false
	if t_enter <= 0.0:
		return true
	return t_enter >= 0.0 and t_enter <= 1.0


static func _build_adjacency(
	battle_state: BattleState,
	nodes: Array[Vector2],
	blocking_rects: Array[Rect2]
) -> Array:
	var node_count: int = nodes.size()
	var adjacency: Array = _empty_adjacency(node_count)
	for i: int in range(node_count):
		for j: int in range(i + 1, node_count):
			if nodes[i].is_equal_approx(nodes[j]):
				continue
			if not _segment_open(battle_state, blocking_rects, nodes[i], nodes[j]):
				continue
			var weight: float = nodes[i].distance_to(nodes[j])
			if not is_finite(weight) or weight < 0.0:
				continue
			var from_map: Dictionary = adjacency[i]
			var to_map: Dictionary = adjacency[j]
			from_map[j] = weight
			to_map[i] = weight
	return adjacency


static func _next_unvisited(distances: Array[float], visited: Array[bool]) -> int:
	var best_index: int = -1
	var best_distance: float = INF
	for i: int in range(distances.size()):
		if visited[i]:
			continue
		var distance: float = distances[i]
		if is_inf(distance):
			continue
		if best_index < 0:
			best_index = i
			best_distance = distance
			continue
		if distance < best_distance and not is_equal_approx(distance, best_distance):
			best_index = i
			best_distance = distance
		elif is_equal_approx(distance, best_distance) and i < best_index:
			best_index = i
	return best_index


static func _reconstruct_route(nodes: Array[Vector2], previous: Array[int]) -> Array[Vector2]:
	var chain: Array[int] = []
	var cursor: int = 1
	var guard: int = nodes.size() + 1
	while cursor >= 0 and chain.size() <= guard:
		chain.append(cursor)
		if cursor == 0:
			break
		cursor = previous[cursor]
	if chain.is_empty() or chain[chain.size() - 1] != 0:
		return []
	var route: Array[Vector2] = []
	var index: int = chain.size() - 1
	while index >= 0:
		route.append(nodes[chain[index]])
		index -= 1
	return route


static func _simplify_route(battle_state: BattleState, route: Array[Vector2]) -> Array[Vector2]:
	if route.size() <= 1:
		return []
	var blocking_rects: Array[Rect2] = _collect_blocking_rects(battle_state)
	var simplified: Array[Vector2] = []
	var current_index: int = 0
	while current_index < route.size() - 1:
		var farthest: int = current_index + 1
		var probe: int = route.size() - 1
		while probe > current_index + 1:
			if _segment_open(battle_state, blocking_rects, route[current_index], route[probe]):
				farthest = probe
				break
			probe -= 1
		if simplified.is_empty() or not simplified[simplified.size() - 1].is_equal_approx(route[farthest]):
			simplified.append(route[farthest])
		current_index = farthest
	return simplified


static func _route_uses_detour(waypoints: Array[Vector2], destination: Vector2) -> bool:
	if waypoints.size() != 1:
		return true
	return not waypoints[0].is_equal_approx(destination)


static func _blocking_obstacle_id(geometry: BattlefieldGeometry, point: Vector2) -> String:
	return geometry.get_movement_blocking_obstacle_id_at(point)

