class_name BattleSpatialService
extends RefCounted

const BattleState := preload("res://battle/core/battle_state.gd")
const BattlefieldGeometry := preload("res://battle/geometry/battlefield_geometry.gd")
const BattleObstacle := preload("res://battle/geometry/battle_obstacle.gd")
const BattleVehicleBodyService := preload("res://battle/vehicles/battle_vehicle_body_service.gd")
const BattleVehicle := preload("res://battle/core/battle_vehicle.gd")
const BattleSpatialResult := preload("res://battle/geometry/battle_spatial_result.gd")

# Participants are treated as points at battle_position. A later body radius can
# be introduced here without changing movement intent or runtime architecture.
const COLLISION_EPSILON := 0.0001
const NO_HIT := INF


static func resolve_translation(
	battle_state: BattleState,
	start_position: Vector2,
	requested_displacement: Vector2
) -> BattleSpatialResult:
	if battle_state == null:
		return BattleSpatialResult.failed(
			"null_battle_state",
			"Battle spatial resolution failed: battle_state is null.",
			start_position,
			requested_displacement
		)
	if battle_state.battlefield_geometry == null:
		return BattleSpatialResult.failed(
			"missing_battlefield_geometry",
			"Battle spatial resolution failed: battlefield geometry is missing.",
			start_position,
			requested_displacement
		)
	var geometry: BattlefieldGeometry = battle_state.battlefield_geometry
	if not battle_state.has_valid_geometry():
		return BattleSpatialResult.failed(
			"invalid_battlefield_geometry",
			"Battle spatial resolution failed: battlefield geometry is invalid.",
			start_position,
			requested_displacement
		)
	if not BattlefieldGeometry.is_finite_point(start_position):
		return BattleSpatialResult.failed(
			"invalid_start_position",
			"Battle spatial resolution failed: start position is invalid.",
			start_position,
			requested_displacement
		)
	if not BattlefieldGeometry.is_finite_point(requested_displacement):
		return BattleSpatialResult.failed(
			"invalid_displacement",
			"Battle spatial resolution failed: requested displacement is invalid.",
			start_position,
			requested_displacement
		)
	if not geometry.contains_point(start_position):
		return BattleSpatialResult.failed(
			"start_outside_battlefield",
			"Battle spatial resolution failed: start position is outside the battlefield.",
			start_position,
			requested_displacement
		)
	var inside_obstacle_id: String = _blocking_obstacle_at(geometry, start_position)
	if not inside_obstacle_id.is_empty():
		return BattleSpatialResult.failed(
			"start_inside_blocking_obstacle",
			"Battle spatial resolution failed: start position is inside blocking obstacle '%s'." % inside_obstacle_id,
			start_position,
			requested_displacement,
			inside_obstacle_id
		)
	var inside_vehicle_id: String = BattleVehicleBodyService.blocking_vehicle_id_at(
		battle_state,
		start_position
	)
	if not inside_vehicle_id.is_empty():
		return BattleSpatialResult.failed(
			"start_inside_vehicle",
			"Battle spatial resolution failed: start position is inside vehicle '%s'." % inside_vehicle_id,
			start_position,
			requested_displacement,
			inside_vehicle_id
		)
	if requested_displacement.is_equal_approx(Vector2.ZERO):
		return BattleSpatialResult.succeeded(
			start_position,
			requested_displacement,
			Vector2.ZERO,
			start_position,
			false,
			""
		)
	return _resolve_legal_translation(battle_state, geometry, start_position, requested_displacement)


# Raw AABB slab overlap for start + t * displacement.
# Returns Vector2(t_enter, t_exit). A miss is encoded as t_enter > t_exit.
static func segment_aabb_overlap_t(
	start_position: Vector2,
	displacement: Vector2,
	rect: Rect2
) -> Vector2:
	var miss: Vector2 = Vector2(INF, -INF)
	if not BattlefieldGeometry.rect_is_usable(rect):
		return miss
	var min_x: float = rect.position.x
	var min_y: float = rect.position.y
	var max_x: float = rect.position.x + rect.size.x
	var max_y: float = rect.position.y + rect.size.y
	var t_enter: float = -INF
	var t_exit: float = INF
	if is_zero_approx(displacement.x):
		if start_position.x < min_x or start_position.x > max_x:
			return miss
	else:
		var t1: float = (min_x - start_position.x) / displacement.x
		var t2: float = (max_x - start_position.x) / displacement.x
		if t1 > t2:
			var swap_t: float = t1
			t1 = t2
			t2 = swap_t
		t_enter = maxf(t_enter, t1)
		t_exit = minf(t_exit, t2)
	if is_zero_approx(displacement.y):
		if start_position.y < min_y or start_position.y > max_y:
			return miss
	else:
		var t1y: float = (min_y - start_position.y) / displacement.y
		var t2y: float = (max_y - start_position.y) / displacement.y
		if t1y > t2y:
			var swap_y: float = t1y
			t1y = t2y
			t2y = swap_y
		t_enter = maxf(t_enter, t1y)
		t_exit = minf(t_exit, t2y)
	if t_enter > t_exit:
		return miss
	return Vector2(t_enter, t_exit)


static func is_translation_clear(
	battle_state: BattleState,
	start_position: Vector2,
	destination: Vector2
) -> bool:
	if not BattlefieldGeometry.is_finite_point(start_position):
		return false
	if not BattlefieldGeometry.is_finite_point(destination):
		return false
	var displacement: Vector2 = destination - start_position
	if not BattlefieldGeometry.is_finite_point(displacement):
		return false
	var result: BattleSpatialResult = resolve_translation(
		battle_state,
		start_position,
		displacement
	)
	if result == null or not result.success:
		return false
	if result.was_blocked:
		return false
	return result.final_position.is_equal_approx(destination)


# Boolean clearance for visibility-graph edges. Same blockers as
# is_translation_clear, without allocating a spatial result or searching
# for the earliest hit. assume_legal_endpoints skips point-in-blocker
# retests when both ends were already accepted as navigation nodes.
static func is_open_segment(
	battle_state: BattleState,
	start_position: Vector2,
	destination: Vector2,
	assume_legal_endpoints: bool = false
) -> bool:
	if battle_state == null or battle_state.battlefield_geometry == null:
		return false
	if not BattlefieldGeometry.is_finite_point(start_position):
		return false
	if not BattlefieldGeometry.is_finite_point(destination):
		return false
	var geometry: BattlefieldGeometry = battle_state.battlefield_geometry
	if not battle_state.has_valid_geometry():
		return false
	if not assume_legal_endpoints:
		if not geometry.contains_point(start_position) or not geometry.contains_point(destination):
			return false
	if start_position.is_equal_approx(destination):
		return true
	if not assume_legal_endpoints:
		if not _blocking_obstacle_at(geometry, start_position).is_empty():
			return false
		if not BattleVehicleBodyService.blocking_vehicle_id_at(battle_state, start_position).is_empty():
			return false
	var displacement: Vector2 = destination - start_position
	if not BattlefieldGeometry.is_finite_point(displacement):
		return false
	for obstacle_id: String in geometry.get_obstacle_ids_in_rect(Rect2(start_position.min(destination), displacement.abs()).grow(COLLISION_EPSILON)):
		var obstacle: BattleObstacle = geometry.obstacles[obstacle_id]
		if obstacle == null or not obstacle.blocks_movement:
			continue
		if not obstacle.bounds_are_usable():
			continue
		var hit_t: float = _segment_rect_entry_t(start_position, displacement, obstacle.bounds)
		if is_inf(hit_t):
			continue
		if hit_t < 0.0 or hit_t > 1.0:
			continue
		return false
	for vehicle_id: String in battle_state.vehicles:
		var vehicle: BattleVehicle = battle_state.vehicles[vehicle_id]
		var hit_t: float = BattleVehicleBodyService.segment_entry_t(
			vehicle,
			start_position,
			displacement
		)
		if is_inf(hit_t):
			continue
		if hit_t < 0.0 or hit_t > 1.0:
			continue
		return false
	if not assume_legal_endpoints:
		if not _blocking_obstacle_at(geometry, destination).is_empty():
			return false
		if not BattleVehicleBodyService.blocking_vehicle_id_at(battle_state, destination).is_empty():
			return false
	return true


static func _resolve_legal_translation(
	battle_state: BattleState,
	geometry: BattlefieldGeometry,
	start_position: Vector2,
	requested_displacement: Vector2
) -> BattleSpatialResult:
	var requested_end: Vector2 = start_position + requested_displacement
	var best_t: float = 1.0
	var best_obstacle_id: String = ""
	var blocked_by_boundary: bool = false
	var boundary_t: float = _battlefield_exit_t(geometry, start_position, requested_displacement)
	if boundary_t < 1.0:
		best_t = boundary_t
		blocked_by_boundary = true
	var obstacle_ids: Array[String] = geometry.get_obstacle_ids_in_rect(Rect2(start_position.min(requested_end), requested_displacement.abs()).grow(COLLISION_EPSILON))
	for obstacle_id: String in obstacle_ids:
		var obstacle: BattleObstacle = geometry.get_obstacle(obstacle_id)
		if obstacle == null or not obstacle.blocks_movement:
			continue
		if not obstacle.bounds_are_usable():
			continue
		var hit_t: float = _segment_rect_entry_t(start_position, requested_displacement, obstacle.bounds)
		if is_inf(hit_t):
			continue
		if hit_t < 0.0 or hit_t > 1.0:
			continue
		if _is_earlier_hit(hit_t, obstacle_id, best_t, best_obstacle_id, blocked_by_boundary):
			best_t = hit_t
			best_obstacle_id = obstacle_id
			blocked_by_boundary = false
	var vehicle_ids: Array[String] = []
	for vehicle_id: String in battle_state.vehicles:
		vehicle_ids.append(vehicle_id)
	vehicle_ids.sort()
	for vehicle_id: String in vehicle_ids:
		var vehicle: BattleVehicle = battle_state.get_vehicle(vehicle_id)
		var hit_t: float = BattleVehicleBodyService.segment_entry_t(
			vehicle,
			start_position,
			requested_displacement
		)
		if is_inf(hit_t):
			continue
		if hit_t < 0.0 or hit_t > 1.0:
			continue
		if _is_earlier_hit(hit_t, vehicle_id, best_t, best_obstacle_id, blocked_by_boundary):
			best_t = hit_t
			best_obstacle_id = vehicle_id
			blocked_by_boundary = false
	var was_blocked: bool = blocked_by_boundary or not best_obstacle_id.is_empty()
	var final_position: Vector2 = requested_end
	if was_blocked:
		final_position = _position_at_hit(
			battle_state,
			geometry,
			start_position,
			requested_displacement,
			best_t,
			best_obstacle_id
		)
	final_position = _clamp_to_battlefield(geometry, final_position)
	if not geometry.contains_point(final_position):
		final_position = start_position
	if not _blocking_obstacle_at(geometry, final_position).is_empty():
		final_position = start_position
	if not BattleVehicleBodyService.blocking_vehicle_id_at(battle_state, final_position).is_empty():
		final_position = start_position
	var resolved_displacement: Vector2 = final_position - start_position
	if not BattlefieldGeometry.is_finite_point(resolved_displacement) or not BattlefieldGeometry.is_finite_point(final_position):
		return BattleSpatialResult.succeeded(
			start_position,
			requested_displacement,
			Vector2.ZERO,
			start_position,
			true,
			best_obstacle_id
		)
	return BattleSpatialResult.succeeded(
		start_position,
		requested_displacement,
		resolved_displacement,
		final_position,
		was_blocked,
		best_obstacle_id
	)


static func _is_earlier_hit(
	hit_t: float,
	obstacle_id: String,
	best_t: float,
	best_obstacle_id: String,
	blocked_by_boundary: bool
) -> bool:
	if hit_t < best_t and not is_equal_approx(hit_t, best_t):
		return true
	if not is_equal_approx(hit_t, best_t):
		return false
	if blocked_by_boundary or best_obstacle_id.is_empty():
		return true
	return obstacle_id < best_obstacle_id


static func _position_at_hit(
	battle_state: BattleState,
	geometry: BattlefieldGeometry,
	start_position: Vector2,
	requested_displacement: Vector2,
	hit_t: float,
	obstacle_id: String
) -> Vector2:
	var t: float = hit_t
	if t < 0.0:
		t = 0.0
	if t > 1.0:
		t = 1.0
	if not obstacle_id.is_empty():
		var path_length: float = requested_displacement.length()
		if not is_finite(path_length) or path_length <= COLLISION_EPSILON:
			return start_position
		var t_back: float = COLLISION_EPSILON / path_length
		t -= t_back
		if t < 0.0:
			t = 0.0
	var point: Vector2 = start_position + requested_displacement * t
	if not obstacle_id.is_empty():
		var obstacle: BattleObstacle = geometry.get_obstacle(obstacle_id)
		if obstacle != null and obstacle.contains_point(point):
			return start_position
		if battle_state != null and battle_state.has_vehicle(obstacle_id):
			var vehicle: BattleVehicle = battle_state.get_vehicle(obstacle_id)
			if BattleVehicleBodyService.contains_point(vehicle, point):
				return start_position
	return point


static func _battlefield_exit_t(
	geometry: BattlefieldGeometry,
	start_position: Vector2,
	displacement: Vector2
) -> float:
	var requested_end: Vector2 = start_position + displacement
	if geometry.contains_point(requested_end):
		return 1.0
	var t: float = 1.0
	if displacement.x > 0.0:
		t = minf(t, (geometry.width - start_position.x) / displacement.x)
	elif displacement.x < 0.0:
		t = minf(t, (0.0 - start_position.x) / displacement.x)
	if displacement.y > 0.0:
		t = minf(t, (geometry.height - start_position.y) / displacement.y)
	elif displacement.y < 0.0:
		t = minf(t, (0.0 - start_position.y) / displacement.y)
	if t < 0.0:
		return 0.0
	if t > 1.0:
		return 1.0
	return t


static func _segment_rect_entry_t(
	start_position: Vector2,
	displacement: Vector2,
	rect: Rect2
) -> float:
	var segment_bounds: Rect2 = Rect2(start_position.min(start_position + displacement), displacement.abs()).grow(COLLISION_EPSILON)
	if not rect.intersects(segment_bounds, true):
		return NO_HIT
	var overlap: Vector2 = segment_aabb_overlap_t(start_position, displacement, rect)
	var t_enter: float = overlap.x
	var t_exit: float = overlap.y
	if t_enter > t_exit:
		return NO_HIT
	if t_exit < 0.0:
		return NO_HIT
	if t_enter > 1.0:
		return NO_HIT
	if t_enter <= 0.0:
		return 0.0
	return t_enter


static func _blocking_obstacle_at(geometry: BattlefieldGeometry, point: Vector2) -> String:
	return geometry.get_movement_blocking_obstacle_id_at(point)

static func _clamp_to_battlefield(geometry: BattlefieldGeometry, point: Vector2) -> Vector2:
	if not BattlefieldGeometry.is_finite_point(point):
		return point
	return Vector2(
		clampf(point.x, 0.0, geometry.width),
		clampf(point.y, 0.0, geometry.height)
	)

battle/vehicles/battle_vehicle_body_serv:
class_name BattleVehicleBodyService
extends RefCounted

# Authoritative derived tactical vehicle body.
# Position + facing + physical profile produce one oriented footprint.
# Renderer, placement, movement, and cover must use these queries.

const BattleState := preload("res://battle/core/battle_state.gd")
const BattleVehicle := preload("res://battle/core/battle_vehicle.gd")
const BattleParticipant := preload("res://battle/core/battle_participant.gd")
const BattlefieldGeometry := preload("res://battle/geometry/battlefield_geometry.gd")
const BattleObstacle := preload("res://battle/geometry/battle_obstacle.gd")
const BattleVehiclePhysicalCatalog := preload("res://battle/vehicles/battle_vehicle_physical_catalog.gd")
const BattleVehiclePhysicalProfile := preload("res://battle/vehicles/battle_vehicle_physical_profile.gd")

const PROJECTION_EPSILON := 0.0001
const NO_HIT := INF


static func profile_for_vehicle(vehicle: BattleVehicle) -> BattleVehiclePhysicalProfile:
	if vehicle == null:
		return null
	return BattleVehiclePhysicalCatalog.get_profile(vehicle.vehicle_type_id)


static func has_usable_pose(vehicle: BattleVehicle) -> bool:
	if vehicle == null:
		return false
	if not vehicle.has_battle_position:
		return false
	if not BattlefieldGeometry.is_finite_point(vehicle.battle_position):
		return false
	return vehicle.has_valid_orientation()


static func world_to_local(world_point: Vector2, position: Vector2, facing: Vector2) -> Vector2:
	var delta: Vector2 = world_point - position
	return delta.rotated(-facing.angle())


static func local_to_world(local_point: Vector2, position: Vector2, facing: Vector2) -> Vector2:
	return position + local_point.rotated(facing.angle())


static func local_aabb(profile: BattleVehiclePhysicalProfile) -> Rect2:
	if profile == null or not profile.is_valid():
		return Rect2()
	return Rect2(-profile.half_length(), -profile.half_width(), profile.length, profile.width)


static func world_corners(vehicle: BattleVehicle) -> PackedVector2Array:
	var corners: PackedVector2Array = PackedVector2Array()
	if not has_usable_pose(vehicle):
		return corners
	var profile: BattleVehiclePhysicalProfile = profile_for_vehicle(vehicle)
	if profile == null:
		return corners
	return corners_for_pose(vehicle.battle_position, vehicle.facing_direction, profile)


static func cleared_corners(vehicle: BattleVehicle, epsilon: float) -> PackedVector2Array:
	var corners: PackedVector2Array = PackedVector2Array()
	if not has_usable_pose(vehicle):
		return corners
	var profile: BattleVehiclePhysicalProfile = profile_for_vehicle(vehicle)
	if profile == null:
		return corners
	var clearance: float = 0.0
	if is_finite(epsilon) and epsilon > 0.0:
		clearance = epsilon
	var hl: float = profile.half_length() + clearance
	var hw: float = profile.half_width() + clearance
	var locals: Array[Vector2] = [
		Vector2(hl, -hw),
		Vector2(hl, hw),
		Vector2(-hl, hw),
		Vector2(-hl, -hw),
	]
	for local_point: Vector2 in locals:
		corners.append(local_to_world(local_point, vehicle.battle_position, vehicle.facing_direction))
	return corners


static func corners_for_pose(
	position: Vector2,
	facing: Vector2,
	profile: BattleVehiclePhysicalProfile
) -> PackedVector2Array:
	var corners: PackedVector2Array = PackedVector2Array()
	if profile == null or not profile.is_valid():
		return corners
	if not BattlefieldGeometry.is_finite_point(position):
		return corners
	if not _facing_is_usable(facing):
		return corners
	var hl: float = profile.half_length()
	var hw: float = profile.half_width()
	var locals: Array[Vector2] = [
		Vector2(hl, -hw),
		Vector2(hl, hw),
		Vector2(-hl, hw),
		Vector2(-hl, -hw),
	]
	for local_point: Vector2 in locals:
		corners.append(local_to_world(local_point, position, facing))
	return corners


static func contains_point(vehicle: BattleVehicle, point: Vector2) -> bool:
	if not has_usable_pose(vehicle):
		return false
	var profile: BattleVehiclePhysicalProfile = BattleVehiclePhysicalCatalog._get_collision_profile(vehicle.vehicle_type_id)
	if profile == null:
		return false
	return pose_contains_point(vehicle.battle_position, vehicle.facing_direction, profile, point)


static func pose_contains_point(
	position: Vector2,
	facing: Vector2,
	profile: BattleVehiclePhysicalProfile,
	point: Vector2
) -> bool:
	if profile == null or not profile.is_valid():
		return false
	if not BattlefieldGeometry.is_finite_point(position) or not BattlefieldGeometry.is_finite_point(point):
		return false
	if not _facing_is_usable(facing):
		return false
	var local_point: Vector2 = world_to_local(point, position, facing)
	var aabb: Rect2 = local_aabb(profile)
	return (
		local_point.x >= aabb.position.x
		and local_point.y >= aabb.position.y
		and local_point.x <= aabb.position.x + aabb.size.x
		and local_point.y <= aabb.position.y + aabb.size.y
	)


static func bodies_intersect(a: BattleVehicle, b: BattleVehicle) -> bool:
	if a == null or b == null:
		return false
	if not has_usable_pose(a) or not has_usable_pose(b):
		return false
	var profile_a: BattleVehiclePhysicalProfile = profile_for_vehicle(a)
	var profile_b: BattleVehiclePhysicalProfile = profile_for_vehicle(b)
	if profile_a == null or profile_b == null:
		return false
	return _sat_intersects(
		corners_for_pose(a.battle_position, a.facing_direction, profile_a),
		corners_for_pose(b.battle_position, b.facing_direction, profile_b)
	)


static func pose_intersects_vehicle(
	position: Vector2,
	facing: Vector2,
	profile: BattleVehiclePhysicalProfile,
	other: BattleVehicle
) -> bool:
	if other == null or not has_usable_pose(other):
		return false
	var other_profile: BattleVehiclePhysicalProfile = profile_for_vehicle(other)
	if other_profile == null:
		return false
	return _sat_intersects(
		corners_for_pose(position, facing, profile),
		corners_for_pose(other.battle_position, other.facing_direction, other_profile)
	)


static func pose_intersects_rect(
	position: Vector2,
	facing: Vector2,
	profile: BattleVehiclePhysicalProfile,
	rect: Rect2
) -> bool:
	if not BattlefieldGeometry.rect_is_usable(rect):
		return false
	var obb: PackedVector2Array = corners_for_pose(position, facing, profile)
	if obb.size() != 4:
		return false
	var aabb: PackedVector2Array = PackedVector2Array([
		rect.position,
		rect.position + Vector2(rect.size.x, 0.0),
		rect.position + rect.size,
		rect.position + Vector2(0.0, rect.size.y),
	])
	return _sat_intersects(obb, aabb)


static func pose_contained_in_rect(
	position: Vector2,
	facing: Vector2,
	profile: BattleVehiclePhysicalProfile,
	rect: Rect2
) -> bool:
	var corners: PackedVector2Array = corners_for_pose(position, facing, profile)
	if corners.size() != 4:
		return false
	for corner: Vector2 in corners:
		if not BattlefieldGeometry.rect_contains_point(rect, corner):
			return false
	return true


static func segment_entry_t(
	vehicle: BattleVehicle,
	start_position: Vector2,
	displacement: Vector2
) -> float:
	if not has_usable_pose(vehicle):
		return NO_HIT
	var profile: BattleVehiclePhysicalProfile = BattleVehiclePhysicalCatalog._get_collision_profile(vehicle.vehicle_type_id)
	if profile == null:
		return NO_HIT
	if not BattlefieldGeometry.is_finite_point(start_position):
		return NO_HIT
	if not BattlefieldGeometry.is_finite_point(displacement):
		return NO_HIT
	# A conservative square contains every orientation of this body. Reject
	# distant segments before rotations and the exact local-space slab test.
	var radius: float = (profile.length + profile.width) * 0.5 + PROJECTION_EPSILON
	var end_position: Vector2 = start_position + displacement
	var center: Vector2 = vehicle.battle_position
	if maxf(start_position.x, end_position.x) < center.x - radius or minf(start_position.x, end_position.x) > center.x + radius:
		return NO_HIT
	if maxf(start_position.y, end_position.y) < center.y - radius or minf(start_position.y, end_position.y) > center.y + radius:
		return NO_HIT
	var facing: Vector2 = vehicle.facing_direction
	var local_start: Vector2 = world_to_local(start_position, vehicle.battle_position, facing)
	var local_end: Vector2 = world_to_local(start_position + displacement, vehicle.battle_position, facing)
	var local_disp: Vector2 = local_end - local_start
	return _local_aabb_entry_t(local_start, local_disp, local_aabb(profile))


static func blocking_vehicle_id_at(battle_state: BattleState, point: Vector2) -> String:
	if battle_state == null or not BattlefieldGeometry.is_finite_point(point):
		return ""
	for vehicle_id: String in _sorted_vehicle_ids(battle_state):
		var vehicle: BattleVehicle = battle_state.get_vehicle(vehicle_id)
		if contains_point(vehicle, point):
			return vehicle_id
	return ""


static func get_placement_error(
	battle_state: BattleState,
	vehicle_id: String,
	position: Vector2,
	facing: Vector2
) -> String:
	if battle_state == null:
		return "null_battle_state"
	if vehicle_id.is_empty() or not battle_state.has_vehicle(vehicle_id):
		return "unknown_vehicle"
	var vehicle: BattleVehicle = battle_state.get_vehicle(vehicle_id)
	if vehicle == null:
		return "unknown_vehicle"
	if not BattlefieldGeometry.is_finite_point(position):
		return "invalid_position"
	if not _facing_is_usable(facing):
		return "invalid_orientation"
	var profile: BattleVehiclePhysicalProfile = profile_for_vehicle(vehicle)
	if profile == null:
		return "missing_profile"
	if battle_state.battlefield_geometry == null or not battle_state.has_valid_geometry():
		return "missing_battlefield_geometry"
	var geometry: BattlefieldGeometry = battle_state.battlefield_geometry
	if not pose_contained_in_rect(position, facing, profile, geometry.bounds()):
		return "outside_battlefield"
	var zone_rect: Rect2 = _side_deployment_rect(battle_state, vehicle.side_id)
	if not BattlefieldGeometry.rect_is_usable(zone_rect):
		return "unknown_side"
	if not _pose_contained_in_side_deployment(
		battle_state,
		vehicle.side_id,
		position,
		facing,
		profile
	):
		return "outside_deployment_zone"
	for obstacle_id: String in geometry.get_sorted_obstacle_ids():
		var obstacle: BattleObstacle = geometry.get_obstacle(obstacle_id)
		if obstacle == null or not obstacle.blocks_movement:
			continue
		if not obstacle.bounds_are_usable():
			continue
		if pose_intersects_rect(position, facing, profile, obstacle.bounds):
			return "inside_blocking_obstacle"
	for other_id: String in _sorted_vehicle_ids(battle_state):
		if other_id == vehicle_id:
			continue
		var other: BattleVehicle = battle_state.get_vehicle(other_id)
		if pose_intersects_vehicle(position, facing, profile, other):
			return "overlaps_vehicle"
	for participant_id: String in _sorted_participant_ids(battle_state):
		var participant: BattleParticipant = battle_state.get_participant(participant_id)
		if participant == null or not participant.has_battle_position:
			continue
		if not BattlefieldGeometry.is_finite_point(participant.battle_position):
			continue
		if pose_contains_point(position, facing, profile, participant.battle_position):
			return "overlaps_participant"
	return ""


static func _local_aabb_entry_t(
	start_position: Vector2,
	displacement: Vector2,
	rect: Rect2
) -> float:
	var overlap: Vector2 = _segment_aabb_overlap_t(start_position, displacement, rect)
	var t_enter: float = overlap.x
	var t_exit: float = overlap.y
	if t_enter > t_exit:
		return NO_HIT
	if t_exit < 0.0:
		return NO_HIT
	if t_enter > 1.0:
		return NO_HIT
	if t_enter <= 0.0:
		return 0.0
	return t_enter


static func _segment_aabb_overlap_t(
	start_position: Vector2,
	displacement: Vector2,
	rect: Rect2
) -> Vector2:
	var miss: Vector2 = Vector2(INF, -INF)
	if not BattlefieldGeometry.rect_is_usable(rect):
		return miss
	var min_x: float = rect.position.x
	var min_y: float = rect.position.y
	var max_x: float = rect.position.x + rect.size.x
	var max_y: float = rect.position.y + rect.size.y
	var t_enter: float = -INF
	var t_exit: float = INF
	if is_zero_approx(displacement.x):
		if start_position.x < min_x or start_position.x > max_x:
			return miss
	else:
		var t1: float = (min_x - start_position.x) / displacement.x
		var t2: float = (max_x - start_position.x) / displacement.x
		if t1 > t2:
			var swap_t: float = t1
			t1 = t2
			t2 = swap_t
		t_enter = maxf(t_enter, t1)
		t_exit = minf(t_exit, t2)
	if is_zero_approx(displacement.y):
		if start_position.y < min_y or start_position.y > max_y:
			return miss
	else:
		var t1y: float = (min_y - start_position.y) / displacement.y
		var t2y: float = (max_y - start_position.y) / displacement.y
		if t1y > t2y:
			var swap_y: float = t1y
			t1y = t2y
			t2y = swap_y
		t_enter = maxf(t_enter, t1y)
		t_exit = minf(t_exit, t2y)
	if t_enter > t_exit:
		return miss
	return Vector2(t_enter, t_exit)


static func _side_deployment_rect(battle_state: BattleState, side_id: String) -> Rect2:
	if battle_state == null or battle_state.battlefield_geometry == null:
		return Rect2()
	if side_id == battle_state.attacker_side_id:
		return battle_state.battlefield_geometry.attacker_deployment_rect
	if side_id == battle_state.defender_side_id:
		return battle_state.battlefield_geometry.defender_deployment_rect
	return Rect2()


static func _pose_contained_in_side_deployment(
	battle_state: BattleState,
	side_id: String,
	position: Vector2,
	facing: Vector2,
	profile: BattleVehiclePhysicalProfile
) -> bool:
	if battle_state == null or battle_state.battlefield_geometry == null:
		return false
	var geometry: BattlefieldGeometry = battle_state.battlefield_geometry
	var use_pockets: bool = false
	if side_id == battle_state.attacker_side_id:
		use_pockets = geometry.has_attacker_deployment_pockets()
	elif side_id == battle_state.defender_side_id:
		use_pockets = geometry.has_defender_deployment_pockets()
	else:
		return false
	if not use_pockets:
		return pose_contained_in_rect(position, facing, profile, _side_deployment_rect(battle_state, side_id))
	var corners: PackedVector2Array = corners_for_pose(position, facing, profile)
	if corners.size() != 4:
		return false
	for corner: Vector2 in corners:
		if side_id == battle_state.attacker_side_id:
			if not geometry.attacker_deployment_contains(corner):
				return false
		elif not geometry.defender_deployment_contains(corner):
			return false
	return true


static func _facing_is_usable(facing: Vector2) -> bool:
	if not BattlefieldGeometry.is_finite_point(facing):
		return false
	if facing.is_equal_approx(Vector2.ZERO):
		return false
	return is_equal_approx(facing.length(), 1.0)


static func _sat_intersects(a: PackedVector2Array, b: PackedVector2Array) -> bool:
	if a.size() < 3 or b.size() < 3:
		return false
	var axes: Array[Vector2] = []
	_append_edge_axes(axes, a)
	_append_edge_axes(axes, b)
	for axis: Vector2 in axes:
		if axis.is_equal_approx(Vector2.ZERO):
			continue
		var proj_a: Vector2 = _project_range(a, axis)
		var proj_b: Vector2 = _project_range(b, axis)
		if proj_a.y < proj_b.x - PROJECTION_EPSILON:
			return false
		if proj_b.y < proj_a.x - PROJECTION_EPSILON:
			return false
	return true


static func _append_edge_axes(axes: Array[Vector2], corners: PackedVector2Array) -> void:
	var count: int = corners.size()
	var index: int = 0
	while index < count:
		var next_index: int = (index + 1) % count
		var edge: Vector2 = corners[next_index] - corners[index]
		if not edge.is_equal_approx(Vector2.ZERO):
			axes.append(Vector2(-edge.y, edge.x).normalized())
		index += 1


static func _project_range(corners: PackedVector2Array, axis: Vector2) -> Vector2:
	var minimum: float = INF
	var maximum: float = -INF
	for corner: Vector2 in corners:
		var projected: float = corner.dot(axis)
		if projected < minimum:
			minimum = projected
		if projected > maximum:
			maximum = projected
	return Vector2(minimum, maximum)


static func _sorted_vehicle_ids(battle_state: BattleState) -> Array[String]:
	var ids: Array[String] = []
	if battle_state == null:
		return ids
	for vehicle_id: String in battle_state.vehicles:
		ids.append(vehicle_id)
	ids.sort()
	return ids


static func _sorted_participant_ids(battle_state: BattleState) -> Array[String]:
	var ids: Array[String] = []
	if battle_state == null:
		return ids
	for participant_id: String in battle_state.participants:
		ids.append(participant_id)
	ids.sort()
	return ids

battle/core/battle_victory_service.gd:
class_name BattleVictoryService
extends RefCounted

const BattleState := preload("res://battle/core/battle_state.gd")
const BattleParticipant := preload("res://battle/core/battle_participant.gd")
const BattleVictoryResult := preload("res://battle/core/battle_victory_result.gd")

const PHASE_RESOLVED := "resolved"

# Side-level elimination. Does not mutate campaign state or consume RNG.


static func is_living_combat_participant(
	battle_state: BattleState,
	participant: BattleParticipant
) -> bool:
	if battle_state == null or participant == null:
		return false
	if participant.participant_id.is_empty():
		return false
	if not battle_state.has_participant(participant.participant_id):
		return false
	if not participant.is_alive:
		return false
	if participant.side_id.is_empty():
		return false
	if not battle_state.has_side(participant.side_id):
		return false
	return true


static func collect_living_side_ids(battle_state: BattleState) -> Array[String]:
	var living_sides: Dictionary[String, bool] = {}
	if battle_state == null:
		return []
	for participant_id: String in _sorted_participant_ids(battle_state):
		var participant: BattleParticipant = battle_state.get_participant(participant_id)
		if not is_living_combat_participant(battle_state, participant):
			continue
		living_sides[participant.side_id] = true
	var living_side_ids: Array[String] = []
	for side_id: String in battle_state.sides:
		if living_sides.has(side_id):
			living_side_ids.append(side_id)
	living_side_ids.sort()
	return living_side_ids


static func can_evaluate(battle_state: BattleState) -> bool:
	if battle_state == null:
		return false
	if battle_state.battle_phase != "active":
		return false
	if battle_state.attacker_side_id.is_empty() or battle_state.defender_side_id.is_empty():
		return false
	if not battle_state.has_side(battle_state.attacker_side_id):
		return false
	if not battle_state.has_side(battle_state.defender_side_id):
		return false
	if battle_state.participants.is_empty():
		return false
	if not battle_state.is_battle_ready():
		return false
	return true


static func is_resolved(battle_state: BattleState) -> bool:
	if battle_state == null:
		return false
	if battle_state.battle_phase == PHASE_RESOLVED:
		return true
	if battle_state.tactical_result != null and battle_state.tactical_result.resolved:
		return true
	return false


static func get_result(battle_state: BattleState) -> BattleVictoryResult:
	if battle_state == null:
		return BattleVictoryResult.ineligible(
			"null_battle_state",
			"Battle victory failed: battle_state is null."
		)
	if battle_state.tactical_result != null:
		return BattleVictoryResult.from_stored(battle_state.tactical_result)
	if battle_state.battle_phase == "active":
		return BattleVictoryResult.continuing(collect_living_side_ids(battle_state))
	return BattleVictoryResult.ineligible(
		"battle_not_resolved",
		"Battle victory failed: battle phase is '%s' and has no tactical result."
		% battle_state.battle_phase
	)


static func get_winning_side_id(battle_state: BattleState) -> String:
	var stored: BattleVictoryResult = get_result(battle_state)
	if stored == null or not stored.resolved:
		return ""
	return stored.winning_side_id


static func get_result_kind(battle_state: BattleState) -> String:
	var stored: BattleVictoryResult = get_result(battle_state)
	if stored == null or not stored.resolved:
		return BattleVictoryResult.RESULT_NONE
	return stored.result_kind


static func is_terminal_state(battle_state: BattleState) -> bool:
	if is_resolved(battle_state):
		return true
	if not can_evaluate(battle_state):
		return false
	return collect_living_side_ids(battle_state).size() <= 1


static func should_halt_autonomous_combat(battle_state: BattleState) -> bool:
	return is_terminal_state(battle_state)


static func evaluate(battle_state: BattleState) -> BattleVictoryResult:
	if battle_state == null:
		return BattleVictoryResult.ineligible(
			"null_battle_state",
			"Battle victory failed: battle_state is null."
		)
	if is_resolved(battle_state):
		return BattleVictoryResult.from_stored(battle_state.tactical_result)
	if not can_evaluate(battle_state):
		if battle_state.battle_phase != "active":
			return BattleVictoryResult.ineligible(
				"battle_not_active",
				"Battle victory failed: battle phase is '%s', not active." % battle_state.battle_phase
			)
		return BattleVictoryResult.ineligible(
			"battle_not_ready",
			"Battle victory failed: battle is not ready for terminal evaluation."
		)
	var living_side_ids: Array[String] = collect_living_side_ids(battle_state)
	if living_side_ids.size() > 1:
		return BattleVictoryResult.continuing(living_side_ids)
	return _terminal_snapshot(battle_state, living_side_ids, false)


static func resolve_if_terminal(battle_state: BattleState) -> BattleVictoryResult:
	if battle_state == null:
		return BattleVictoryResult.ineligible(
			"null_battle_state",
			"Battle victory failed: battle_state is null."
		)
	if is_resolved(battle_state):
		return BattleVictoryResult.from_stored(battle_state.tactical_result)
	if not can_evaluate(battle_state):
		return evaluate(battle_state)
	var living_side_ids: Array[String] = collect_living_side_ids(battle_state)
	if living_side_ids.size() > 1:
		return BattleVictoryResult.continuing(living_side_ids)
	var stored: BattleVictoryResult = _terminal_snapshot(battle_state, living_side_ids, true)
	battle_state.tactical_result = stored
	battle_state.battle_phase = PHASE_RESOLVED
	return stored


static func _terminal_snapshot(
	battle_state: BattleState,
	living_side_ids: Array[String],
	p_resolved_this_call: bool
) -> BattleVictoryResult:
	var losing_side_ids: Array[String] = _sorted_side_ids(battle_state)
	if living_side_ids.size() == 1:
		var winning_side_id: String = living_side_ids[0]
		var losers: Array[String] = []
		for side_id: String in losing_side_ids:
			if side_id != winning_side_id:
				losers.append(side_id)
		return BattleVictoryResult.resolved_victory(
			winning_side_id,
			losers,
			living_side_ids,
			p_resolved_this_call
		)
	return BattleVictoryResult.resolved_draw(losing_side_ids, p_resolved_this_call)


static func _sorted_participant_ids(battle_state: BattleState) -> Array[String]:
	var ids: Array[String] = []
	if battle_state == null:
		return ids
	for participant_id: String in battle_state.participants:
		ids.append(participant_id)
	ids.sort()
	return ids


static func _sorted_side_ids(battle_state: BattleState) -> Array[String]:
	var ids: Array[String] = []
	if battle_state == null:
		return ids
	for side_id: String in battle_state.sides:
		ids.append(side_id)
	ids.sort()
	return ids

battle/runtime/battle_runtime_service.gd:
class_name BattleRuntimeService
extends RefCounted

const Strength = preload("res://battle/ai/battle_relative_strength.gd")
const Tactics = preload("res://battle/ai/battle_adaptive_tactics.gd")
const BattleState := preload("res://battle/core/battle_state.gd")
const BattleRuntimeResult := preload("res://battle/runtime/battle_runtime_result.gd")
const BattleFireControlService := preload("res://battle/combat/battle_fire_control_service.gd")
const BattleFireControlResult := preload("res://battle/combat/battle_fire_control_result.gd")
const BattleTargetSelectionService := preload("res://battle/combat/battle_target_selection_service.gd")
const BattleTargetSelectionResult := preload("res://battle/combat/battle_target_selection_result.gd")
const BattleCombatPressureService := preload("res://battle/combat/battle_combat_pressure_service.gd")
const BattleCombatPressureResult := preload("res://battle/combat/battle_combat_pressure_result.gd")
const BattleCombatBehaviorService := preload("res://battle/combat/battle_combat_behavior_service.gd")
const BattleCombatBehaviorResult := preload("res://battle/combat/battle_combat_behavior_result.gd")
const BattlePathFollowService := preload("res://battle/navigation/battle_path_follow_service.gd")
const BattlePathFollowResult := preload("res://battle/navigation/battle_path_follow_result.gd")
const BattleMovementService := preload("res://battle/runtime/battle_movement_service.gd")
const BattleMovementResult := preload("res://battle/runtime/battle_movement_result.gd")
const BattleVictoryService := preload("res://battle/core/battle_victory_service.gd")
const BattleVictoryResult := preload("res://battle/core/battle_victory_result.gd")


static func advance(battle_state: BattleState, delta_seconds: float) -> BattleRuntimeResult:
	if battle_state == null:
		return _advance_validated(battle_state, delta_seconds)
	battle_state.begin_geometry_validation_scope()
	var result: BattleRuntimeResult = _advance_validated(battle_state, delta_seconds)
	battle_state.end_geometry_validation_scope()
	return result


static func _advance_validated(battle_state: BattleState, delta_seconds: float) -> BattleRuntimeResult:
	if battle_state == null:
		return BattleRuntimeResult.failed(
			"null_battle_state",
			"Battle runtime failed: battle_state is null.",
			delta_seconds,
			0.0
		)
	battle_state.prepare_los_cache_for_tick()
	var elapsed_before: float = battle_state.elapsed_time_seconds
	if battle_state.battle_phase != "active":
		return BattleRuntimeResult.failed(
			"battle_not_active",
			"Battle runtime failed: battle phase is '%s', not active." % battle_state.battle_phase,
			delta_seconds,
			elapsed_before
		)
	if not is_finite(delta_seconds) or delta_seconds < 0.0:
		return BattleRuntimeResult.failed(
			"invalid_delta",
			"Battle runtime failed: delta_seconds is invalid.",
			delta_seconds,
			elapsed_before
		)
	if not is_finite(elapsed_before) or elapsed_before < 0.0:
		return BattleRuntimeResult.failed(
			"invalid_elapsed_time",
			"Battle runtime failed: elapsed_time_seconds is invalid.",
			delta_seconds,
			elapsed_before
		)
	var early_victory: BattleVictoryResult = BattleVictoryService.resolve_if_terminal(battle_state)
	if early_victory != null and early_victory.success and early_victory.resolved_this_call:
		return _finish_runtime(battle_state, delta_seconds, elapsed_before, early_victory, true)
	var weapon_result: BattleFireControlResult = BattleFireControlService.advance_weapon_state(
		battle_state,
		delta_seconds
	)
	if weapon_result == null or not weapon_result.success:
		var weapon_error_code: String = "invalid_delta"
		var weapon_error_message: String = "Battle runtime failed: weapon state advancement failed."
		if weapon_result != null:
			if not weapon_result.error_code.is_empty():
				weapon_error_code = weapon_result.error_code
			if not weapon_result.error_message.is_empty():
				weapon_error_message = weapon_result.error_message
		return BattleRuntimeResult.failed(
			weapon_error_code,
			weapon_error_message,
			delta_seconds,
			elapsed_before
		)
	var target_result: BattleTargetSelectionResult = BattleTargetSelectionService.advance(battle_state)
	if target_result == null or not target_result.success:
		var target_error_code: String = "invalid_delta"
		var target_error_message: String = "Battle runtime failed: target selection failed."
		if target_result != null:
			if not target_result.error_code.is_empty():
				target_error_code = target_result.error_code
			if not target_result.error_message.is_empty():
				target_error_message = target_result.error_message
		return BattleRuntimeResult.failed(
			target_error_code,
			target_error_message,
			delta_seconds,
			elapsed_before
		)
	var pressure_result: BattleCombatPressureResult = BattleCombatPressureService.refresh(battle_state)
	if pressure_result == null or not pressure_result.success:
		var pressure_error_code: String = "invalid_delta"
		var pressure_error_message: String = "Battle runtime failed: combat pressure refresh failed."
		if pressure_result != null:
			if not pressure_result.error_code.is_empty():
				pressure_error_code = pressure_result.error_code
			if not pressure_result.error_message.is_empty():
				pressure_error_message = pressure_result.error_message
		return BattleRuntimeResult.failed(
			pressure_error_code,
			pressure_error_message,
			delta_seconds,
			elapsed_before
		)
	Tactics.advance(battle_state, delta_seconds)
	var combat_result: BattleCombatBehaviorResult = BattleCombatBehaviorService.advance(
		battle_state,
		delta_seconds
	)
	if combat_result == null or not combat_result.success:
		var combat_error_code: String = "invalid_delta"
		var combat_error_message: String = "Battle runtime failed: combat behavior failed."
		if combat_result != null:
			if not combat_result.error_code.is_empty():
				combat_error_code = combat_result.error_code
			if not combat_result.error_message.is_empty():
				combat_error_message = combat_result.error_message
		return BattleRuntimeResult.failed(
			combat_error_code,
			combat_error_message,
			delta_seconds,
			elapsed_before
		)
	var victory_result: BattleVictoryResult = BattleVictoryService.resolve_if_terminal(battle_state)
	if battle_state.battle_phase != "active":
		return _finish_runtime(battle_state, delta_seconds, elapsed_before, victory_result, true)
	var path_follow_result: BattlePathFollowResult = BattlePathFollowService.advance(battle_state)
	if path_follow_result == null or not path_follow_result.success:
		var follow_error_code: String = "invalid_delta"
		var follow_error_message: String = "Battle runtime failed: path following failed."
		if path_follow_result != null:
			if not path_follow_result.error_code.is_empty():
				follow_error_code = path_follow_result.error_code
			if not path_follow_result.error_message.is_empty():
				follow_error_message = path_follow_result.error_message
		return BattleRuntimeResult.failed(
			follow_error_code,
			follow_error_message,
			delta_seconds,
			elapsed_before
		)
	var movement_result: BattleMovementResult = BattleMovementService.advance(battle_state, delta_seconds)
	if movement_result == null or not movement_result.success:
		var error_code: String = "invalid_delta"
		var error_message: String = "Battle runtime failed: movement advancement failed."
		if movement_result != null:
			if not movement_result.error_code.is_empty():
				error_code = movement_result.error_code
			if not movement_result.error_message.is_empty():
				error_message = movement_result.error_message
		return BattleRuntimeResult.failed(
			error_code,
			error_message,
			delta_seconds,
			elapsed_before
		)
	return _finish_runtime(battle_state, delta_seconds, elapsed_before, null, false)


static func _finish_runtime(
	battle_state: BattleState,
	delta_seconds: float,
	elapsed_before: float,
	victory_result: BattleVictoryResult,
	resolved_this_pass: bool
) -> BattleRuntimeResult:
	Strength.refresh(battle_state, battle_state.battle_phase == "resolved")
	var winning_side_id: String = ""
	if victory_result != null and victory_result.success and victory_result.resolved:
		winning_side_id = victory_result.winning_side_id
		if victory_result.resolved_this_call:
			resolved_this_pass = true
	if delta_seconds == 0.0:
		return BattleRuntimeResult.succeeded(
			delta_seconds,
			elapsed_before,
			elapsed_before,
			resolved_this_pass,
			winning_side_id
		)
	battle_state.elapsed_time_seconds = elapsed_before + delta_seconds
	return BattleRuntimeResult.succeeded(
		delta_seconds,
		elapsed_before,
		battle_state.elapsed_time_seconds,
		resolved_this_pass,
		winning_side_id
	)

battle/core/battle_state.gd:
class_name BattleState
extends RefCounted

const BattleSide := preload("res://battle/core/battle_side.gd")
const BattleParticipant := preload("res://battle/core/battle_participant.gd")
